    private function recordFailure(WebhookDelivery $delivery, WebhookEndpoint $endpoint, string $error): void
    {
        $attempts = $delivery->attempts + 1;
310→        $schedule = $this->webhooksConfig->retrySchedule();

        if ($attempts <= count($schedule)) {
            $delivery->forceFill([
                'status' => 'failed',
                'attempts' => $attempts,
                'next_retry_at' => now()->addSeconds($this->jitteredDelay(seconds: $schedule[$attempts - 1])),
                'last_error' => $error,
            ])->save();
        } else {
320→            $delivery->forceFill([
                'status' => 'dead',
                'attempts' => $attempts,
                'next_retry_at' => null,
                'last_error' => $error,
            ])->save();
