    $endpoint = WebhookTestHelpers::endpoint(['failure_count' => 3, 'failing_since' => now()->subDay()]);
    $delivery = WebhookTestHelpers::delivery($endpoint, ['payload' => ['id' => 'evt-1', 'type' => 'folder.created']]);

    runDeliver($delivery);

50→    $delivery->refresh();
